"""Read-only access to HLS artifacts generated by media_manager."""

from __future__ import annotations

import hashlib
import os
from pathlib import Path
from urllib.parse import quote

import httpx
from fastapi import HTTPException

HLS_CACHE_DIR = Path(os.environ.get("HLS_CACHE_DIR", str(Path(os.getenv("TMPDIR", "/tmp")) / "adlv-media-hls")))
CACHE_VERSION = "hls-v6"
SUPABASE_URL = os.environ.get("SUPABASE_URL", "").rstrip("/")
MEDIA_BUCKET = os.environ.get("MEDIA_BUCKET", "media")


def cache_key(media_path: str) -> str:
    return hashlib.sha256(f"{CACHE_VERSION}:{media_path}".encode("utf-8")).hexdigest()


def storage_prefix(media_path: str) -> str:
    path = Path(media_path)
    if path.name == "index.m3u8" and path.parent.name.endswith("-hls"):
        return "/".join(path.parts[:-1])
    return "/".join((*path.parts[:-1], f"{path.stem}-hls"))


def cache_dir(media_path: str) -> Path:
    return HLS_CACHE_DIR / cache_key(media_path)


def manifest_path(media_path: str) -> Path:
    return cache_dir(media_path) / "index.m3u8"


def _storage_path(media_path: str, name: str = "index.m3u8") -> str:
    return f"{storage_prefix(media_path)}/{name}"


def storage_segment_url(media_path: str, segment_name: str) -> str:
    path = _storage_path(media_path, segment_name)
    return f"{SUPABASE_URL}/storage/v1/object/{MEDIA_BUCKET}/{quote(path, safe='/')}"


def storage_headers(headers: dict[str, str]) -> dict[str, str]:
    return dict(headers)


def is_complete(media_path: str) -> bool:
    path = manifest_path(media_path)
    if not path.is_file():
        return False
    try:
        return "#EXT-X-ENDLIST" in path.read_text(encoding="utf-8")
    except OSError:
        return False


def generate(media_path: str, _media_url: str, headers: dict[str, str]) -> Path:
    """Fetch a pre-generated HLS manifest; never transcode or write source media."""
    path = manifest_path(media_path)
    try:
        response = httpx.get(
            f"{SUPABASE_URL}/storage/v1/object/{MEDIA_BUCKET}/{quote(_storage_path(media_path), safe='/')}",
            headers=headers,
            timeout=30,
        )
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail="HLS storage could not be reached.") from exc
    if response.status_code == 404:
        raise HTTPException(status_code=404, detail="HLS has not been generated for this video yet.")
    if response.status_code >= 400:
        raise HTTPException(status_code=502, detail="HLS storage returned an error.")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(response.text, encoding="utf-8")
    return path
